import{_ as o,o as e,c as s,a2 as r}from"./chunks/framework.CqdVOxXJ.js";const g=JSON.parse('{"title":"2. Technician daily guide","description":"","frontmatter":{},"headers":[],"relativePath":"chapters/02-technician-daily-guide.md","filePath":"chapters/02-technician-daily-guide.md","lastUpdated":null}'),n={name:"chapters/02-technician-daily-guide.md"};function a(i,t,l,h,d,c){return e(),s("div",null,[...t[0]||(t[0]=[r('<h1 id="_2-technician-daily-guide" tabindex="-1">2. Technician daily guide <a class="header-anchor" href="#_2-technician-daily-guide" aria-label="Permalink to &quot;2. Technician daily guide&quot;">​</a></h1><p><strong>For:</strong> Lead Technician · <strong>Hubs:</strong> Workshop, Me</p><p>This chapter follows a normal bay day: clock in, pick up your jobs, do the work, prove it with the checklist and photos, and hand the car back to the desk.</p><h2 id="_2-1-start-of-day-clock-in" tabindex="-1">2.1 Start of day: clock in <a class="header-anchor" href="#_2-1-start-of-day-clock-in" aria-label="Permalink to &quot;2.1 Start of day: clock in&quot;">​</a></h2><p>You clock in on your own phone, or on the shop tablet if the owner runs the kiosk.</p><p><strong>On your phone — Me › Time clock (<code>/me/clock</code>)</strong></p><ol><li>Open <strong>Me › Time clock</strong>.</li><li>If the shop needs a photo (&quot;This shop requires a photo on clock-in and clock-out&quot;), take the selfie when asked.</li><li>Press <strong>Clock in</strong>. The app checks your phone location against the shop&#39;s allowed radius.</li><li>Your punch appears under <strong>Today</strong>.</li></ol><p><strong>On the shop tablet — Clock kiosk (<code>/hr/clock-kiosk</code>)</strong> The owner opens the kiosk on a shared device. Tap your name:</p><ul><li>&quot;Clocked out — tap to clock in&quot; → you are now in.</li><li>&quot;Clocked in — tap to clock out&quot; → you are now out.</li></ul><p>The kiosk lists only people set to <strong>Must clock</strong>. If your name is missing, tell the owner.</p><div class="tip custom-block"><p class="custom-block-title">Off-site work</p><p>If you are away from the shop (road test, towing, parts run), the app warns that you are outside the radius. Type a <strong>Reason</strong> and punch anyway. The punch shows as <strong>Pending</strong> until the owner approves it in <strong>HR › Attendance</strong>. See <a href="/rakkii-cars-guide/chapters/03-staff-self-service-me-hub#_3-1-time-clock-me-clock">Chapter 3</a>.</p></div><p>At the end of the day, press <strong>Clock out</strong> the same way. A punch with no clock-out is not paid for that day until the desk closes it.</p><div class="info custom-block"><p class="custom-block-title">📷 Screenshot placeholder</p><p><code>/screenshots/02-technician-daily-guide/01-clock-in.png</code> — Time clock with Clock in and Today&#39;s punches.</p></div><h2 id="_2-2-your-job-list-workshop-›-my-jobs-workshop" tabindex="-1">2.2 Your job list: Workshop › My jobs (<code>/workshop</code>) <a class="header-anchor" href="#_2-2-your-job-list-workshop-›-my-jobs-workshop" aria-label="Permalink to &quot;2.2 Your job list: Workshop › My jobs (`/workshop`)&quot;">​</a></h2><p>Your home page shows two lists:</p><table tabindex="0"><thead><tr><th>List</th><th>What is in it</th><th>What you can do</th></tr></thead><tbody><tr><td><strong>Assigned to me (n)</strong></td><td>Jobs the desk assigned to you</td><td>Open and work them</td></tr><tr><td><strong>Other jobs (n)</strong></td><td>Other open bay jobs, unassigned first, with the technician names</td><td>Open to <strong>view only</strong></td></tr></tbody></table><p>At the top, <strong>Assigned to you</strong> shows new assignments this week, who assigned them and when. Announcements the owner posts also appear here while they are active.</p><ul><li>If you open a job that is not yours and try to change it, the app says <strong>&quot;This job isn&#39;t assigned to you.&quot;</strong> Ask the desk to assign you.</li><li>Jobs are reassigned by the owner (for example when you go on leave). The job keeps an <strong>Assignment history</strong>.</li></ul><div class="info custom-block"><p class="custom-block-title">📷 Screenshot placeholder</p><p><code>/screenshots/02-technician-daily-guide/02-my-jobs.png</code> — My jobs with &quot;Assigned to me&quot; and &quot;Other jobs&quot;.</p></div><h2 id="_2-3-starting-bay-work" tabindex="-1">2.3 Starting bay work <a class="header-anchor" href="#_2-3-starting-bay-work" aria-label="Permalink to &quot;2.3 Starting bay work&quot;">​</a></h2><ol><li>Tap the plate under <strong>Assigned to me</strong>. The job opens on the <strong>Work</strong> tab.</li><li>Read the <strong>Job order</strong>: plate, customer, reference, status, technicians and the work lines (what to do, how many). Prices are not shown to you.</li><li>Read <strong>Notes</strong> for the desk&#39;s instructions.</li><li>Use <strong>Add photo</strong> / <strong>Bay photo</strong> for progress pictures as you go.</li></ol><p>The desk moves the job to <strong>Under repair</strong> when work can start (after the quote, deposit or LOA is in place). You can see the current status at the top of the job.</p><h3 id="your-status-buttons" tabindex="-1">Your status buttons <a class="header-anchor" href="#your-status-buttons" aria-label="Permalink to &quot;Your status buttons&quot;">​</a></h3><p>A technician has only these moves. Everything else (start work, ready for pickup, release) belongs to the desk.</p><table tabindex="0"><thead><tr><th>Button</th><th>From</th><th>Goes to</th></tr></thead><tbody><tr><td><strong>Send to QC</strong></td><td>Under repair</td><td>Quality check</td></tr><tr><td><strong>Waiting for parts</strong></td><td>Under repair</td><td>Waiting for parts</td></tr><tr><td><strong>Parts in — back to shop</strong> / <strong>Back to shop</strong></td><td>Waiting for parts, Quality check, On hold</td><td>Under repair (or the status it was held from)</td></tr><tr><td><strong>Put on hold</strong></td><td>Under repair, Waiting for parts, Quality check</td><td>On hold</td></tr></tbody></table><h3 id="printing-workshop-papers" tabindex="-1">Printing workshop papers <a class="header-anchor" href="#printing-workshop-papers" aria-label="Permalink to &quot;Printing workshop papers&quot;">​</a></h3><p>From the Work tab you can print the <strong>Job order</strong>, <strong>Gate pass</strong>, <strong>QC summary</strong> and <strong>Acceptance</strong> sheets. Money papers (estimate, invoices, payment instructions) are desk-only.</p><h2 id="_2-4-ticking-the-bay-checklist" tabindex="-1">2.4 Ticking the bay checklist <a class="header-anchor" href="#_2-4-ticking-the-bay-checklist" aria-label="Permalink to &quot;2.4 Ticking the bay checklist&quot;">​</a></h2><p>Each job can carry a <strong>Bay checklist</strong> (usually applied by the desk from a template, for example &quot;Body &amp; paint&quot; or &quot;PMS&quot;).</p><ol><li>In <strong>Work › Bay checklist</strong>, tick each step when it is really done. The app records <strong>Done by</strong> your name and the time.</li><li>If a step is missing, type it in <strong>New step</strong> and press <strong>Add step</strong>.</li><li>The job header shows progress (for example &quot;3 open · 5 / 8 done&quot;, then &quot;All done&quot;).</li></ol><div class="warning custom-block"><p class="custom-block-title">Open steps follow the car</p><p>The Shop board and Dashboard flag jobs in Under repair or Quality check that still have open checklist steps. Finish or remove steps before you send the car to QC.</p></div><div class="info custom-block"><p class="custom-block-title">📷 Screenshot placeholder</p><p><code>/screenshots/02-technician-daily-guide/03-bay-checklist.png</code> — Bay checklist with ticked and open steps.</p></div><h2 id="_2-5-putting-a-job-on-hold" tabindex="-1">2.5 Putting a job on hold <a class="header-anchor" href="#_2-5-putting-a-job-on-hold" aria-label="Permalink to &quot;2.5 Putting a job on hold&quot;">​</a></h2><p>Use <strong>Put on hold</strong> when work must stop for a reason outside the bay: the customer has not decided on extra work, the insurer has not approved a supplement, the car needs a part nobody can source yet.</p><p><strong>Who:</strong> the owner, or the technician assigned to that job. <strong>Rules:</strong></p><ol><li>Press <strong>Put on hold</strong> and type a <strong>Reason</strong> (at least 3 characters, up to 500).</li><li>The job shows &quot;On hold: <em>your reason</em>&quot; for everyone.</li><li>To continue, press <strong>Resume</strong>. A held job only goes back to the status it was held from (or the desk cancels it).</li></ol><p>Use <strong>Waiting for parts</strong> instead of hold when you are only waiting for an ordered part.</p><h2 id="_2-6-insurance-jobs-logging-surrendered-parts" tabindex="-1">2.6 Insurance jobs: logging surrendered parts <a class="header-anchor" href="#_2-6-insurance-jobs-logging-surrendered-parts" aria-label="Permalink to &quot;2.6 Insurance jobs: logging surrendered parts&quot;">​</a></h2><p>Insurers often require the damaged parts that were replaced. On insurance jobs the <strong>Work</strong> tab shows a <strong>Surrendered Parts</strong> card (&quot;Parts handed to the insurer&quot;).</p><ol><li>Press <strong>Add part</strong>.</li><li>Fill <strong>Description</strong> (pick from the job&#39;s lines or type), <strong>Qty</strong>, <strong>Surrender date</strong>, <strong>Received by</strong> and an optional <strong>Note</strong>.</li><li>Press <strong>Save</strong>. Edit or delete a row until the job is closed.</li><li>If nothing has to go back to the insurer, tick <strong>No parts to surrender</strong>.</li></ol><p>Until one of these is done the desk sees the hint &quot;No surrendered parts logged.&quot;</p><h2 id="_2-7-canvass-and-parts-buy-only-when-enabled" tabindex="-1">2.7 Canvass and Parts buy (only when enabled) <a class="header-anchor" href="#_2-7-canvass-and-parts-buy-only-when-enabled" aria-label="Permalink to &quot;2.7 Canvass and Parts buy (only when enabled)&quot;">​</a></h2><p>Some technicians are allowed to source and pay for parts. This needs the <strong>Can canvass &amp; pay suppliers</strong> permission on your staff record, and the job must be marked <strong>Needs canvass</strong> and/or <strong>Needs parts buy</strong> by the desk. Only then do the <strong>Canvass</strong> and <strong>Parts buy</strong> tabs appear.</p><h3 id="canvass-tab-—-compare-suppliers" tabindex="-1">Canvass tab — compare suppliers <a class="header-anchor" href="#canvass-tab-—-compare-suppliers" aria-label="Permalink to &quot;Canvass tab — compare suppliers&quot;">​</a></h3><ol><li>Press <strong>Import from estimate</strong> to copy the part lines, or <strong>Add line</strong> for each part (<strong>Part</strong>, <strong>SKU</strong>, <strong>Qty</strong>, <strong>Grade</strong>).</li><li>For each line enter up to four quotes: <strong>Supplier A–D</strong>, <strong>price</strong> and <strong>lead days</strong>.</li><li>Upload supplier quotation files under <strong>Quote files</strong> with a <strong>Supplier label</strong>.</li><li>Press <strong>Choose A / B / C / D</strong> on each line to pick the supplier.</li><li>Move the request along: <strong>Mark sent</strong> → <strong>Mark quotes in</strong> → <strong>Submit</strong>. The status reads Draft, Sent, Quotes in, then Approved.</li><li>The owner presses <strong>Approve</strong>. Approved lines are <strong>Locked</strong>. The owner can <strong>Unlock</strong> for changes.</li></ol><div class="tip custom-block"><p class="custom-block-title">The budget is cost, never sell price</p><p>The canvass header compares <strong>Selected</strong> (your chosen supplier costs) against <strong>Estimate parts</strong>. That budget is quantity × <strong>cost</strong> of the approved part lines on the estimate. The customer&#39;s sell price is never used. If you go over, the app shows &quot;Selected cost exceeds estimate parts budget by …&quot; so the owner can decide.</p></div><h3 id="parts-buy-tab-—-pay-and-receive" tabindex="-1">Parts buy tab — pay and receive <a class="header-anchor" href="#parts-buy-tab-—-pay-and-receive" aria-label="Permalink to &quot;Parts buy tab — pay and receive&quot;">​</a></h3><ol><li>Press <strong>Add purchase</strong> with <strong>Part</strong>, <strong>Supplier</strong>, <strong>Cost</strong>, <strong>Method</strong> and the supplier <strong>Terms</strong> (COD, Term with days, or From Rakkii stock).</li><li>Press <strong>Pay supplier</strong> when you pay. Attach the receipt photo.</li><li>If the shop requires it, the owner must <strong>Release funds</strong> first.</li><li>When the part arrives, press <strong>Mark arrived</strong>. This is blocked while the canvass is still waiting for approval (&quot;Canvass pending approval — mark arrived is blocked until owner/admin approves&quot;).</li><li><strong>Print supplier request</strong> prints a Request for Payment for the parts.</li></ol><p>Statuses: <strong>To pay → Paid → Funds released → Arrived</strong>.</p><h2 id="_2-8-uploading-the-four-qc-photos" tabindex="-1">2.8 Uploading the four QC photos <a class="header-anchor" href="#_2-8-uploading-the-four-qc-photos" aria-label="Permalink to &quot;2.8 Uploading the four QC photos&quot;">​</a></h2><p>A car cannot move to <strong>Ready for pickup</strong> or be <strong>Released</strong> until it has the required QC photos (4 by default). The photo card (&quot;Required before release. Angles: front, rear, left (LS), right (RS).&quot;) is on the <strong>Work</strong> and <strong>Files</strong> tabs.</p><ol><li>Finish the repair and clean-up.</li><li>Under <strong>QC photos</strong>, upload one photo for each angle: <ul><li><strong>Front</strong></li><li><strong>Rear</strong></li><li><strong>Left side (LS)</strong></li><li><strong>Right side (RS)</strong></li></ul></li><li>The counter shows progress, for example <strong>QC photos: 3/4</strong>, and names the missing angle.</li><li>When all four are in, press <strong>Send to QC</strong> (or tell the desk the car is ready).</li></ol><p>Only the owner (or admin) can skip photos, with a written <strong>QC override reason</strong>.</p><div class="info custom-block"><p class="custom-block-title">📷 Screenshot placeholder</p><p><code>/screenshots/02-technician-daily-guide/04-qc-photos.png</code> — QC photos card with Front, Rear, Left side (LS), Right side (RS) slots.</p></div><h2 id="_2-9-checking-the-calendar-and-forms" tabindex="-1">2.9 Checking the calendar and forms <a class="header-anchor" href="#_2-9-checking-the-calendar-and-forms" aria-label="Permalink to &quot;2.9 Checking the calendar and forms&quot;">​</a></h2><p><strong>Workshop › Calendar (<code>/workshop/calendar</code>)</strong> shows promised dates by day. Pick a <strong>Day</strong> to see which cars are due, and <strong>No date yet</strong> for open jobs without a promised date. Use it to plan your bay order.</p><p><strong>Workshop › Forms (<code>/workshop/forms</code>)</strong> has the printable shop forms:</p><ul><li><strong>Vehicle Pick-up &amp; Delivery Waiver</strong> — when you pick up or deliver a customer car outside the shop.</li><li><strong>Undertaking and vehicle intake checklist</strong> — when a car is received: tap panels to mark damage, fuel level, items present.</li></ul><p>Press <strong>Start from job</strong> to link the form to a job so answers are saved on it, or <strong>Print</strong> a blank.</p><h2 id="_2-10-end-of-day-checklist" tabindex="-1">2.10 End-of-day checklist <a class="header-anchor" href="#_2-10-end-of-day-checklist" aria-label="Permalink to &quot;2.10 End-of-day checklist&quot;">​</a></h2><ul><li>[ ] Checklist steps ticked for today&#39;s work</li><li>[ ] Progress photos uploaded</li><li>[ ] Jobs waiting on parts set to <strong>Waiting for parts</strong>; blocked jobs <strong>On hold</strong> with a reason</li><li>[ ] Surrendered parts logged on insurance jobs</li><li>[ ] QC photos (4 angles) on every car you finished</li><li>[ ] <strong>Clock out</strong></li></ul>',61)])])}const u=o(n,[["render",a]]);export{g as __pageData,u as default};
